//! `levels/ffa_runs.lvl` (generated by `scripts/gen_runs_level.py`, `MAP=runs`): THE RUN GAUNTLET. Pinned: a serpentine of five
//! 180 m decks (y 9.6) over a ground floor, cut by gaps that grow 10 -> 18 m; a 7 m run-wall panel over EVERY gap and a hook anchor
//! hung over every gap middle; the platforms in between are NOT walkable (the gaps need wall-run / hook), the turn pads are (ramps);
//! spawns are clear and spread, pickups supported, the geometry fits the engine's numeric limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{parse_level_file, unwalkable_obstacles, LevelBox, LevelFile};
use shinobi_sim::power::PowerKind;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::far_dist;
use std::collections::{HashMap, VecDeque};

const DECK: f32 = 9.6;
const LEG_Z: [f32; 5] = [-56.0, -28.0, 0.0, 28.0, 56.0];
const GAPS: [f32; 5] = [10.0, 12.0, 14.0, 16.0, 18.0];

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_runs.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_runs.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

fn surface_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn top_at(l: &LevelFile, x: f32, z: f32) -> Option<f32> {
    l.level.boxes.iter().filter_map(|b| surface_at(b, x, z)).fold(None, |m: Option<f32>, h| Some(m.map_or(h, |m| m.max(h))))
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

/// The leg platforms (the end pads beyond x = +-90 excluded): flat, 1.2 m thick, top at DECK, 10 m wide (z), as (leg index, x0, x1) sorted along x.
fn platforms(l: &LevelFile) -> Vec<(usize, f32, f32)> {
    let mut out = Vec::new();
    for b in &l.level.boxes {
        if b.rot_z == 0.0 && (b.center[1] + b.half[1] - DECK).abs() < 0.01 && (b.half[1] - 0.6).abs() < 0.01 && (b.half[2] - 5.0).abs() < 0.01 && b.center[0].abs() + b.half[0] <= 90.01 {
            let leg = LEG_Z.iter().position(|z| (z - b.center[2]).abs() < 0.01).expect("a deck off every leg axis");
            out.push((leg, b.center[0] - b.half[0], b.center[0] + b.half[0]));
        }
    }
    out.sort_by(|a, b| a.partial_cmp(b).unwrap());
    out
}

fn gaps(l: &LevelFile) -> Vec<(usize, f32, f32)> {
    let p = platforms(l);
    let mut out = Vec::new();
    for leg in 0..5 {
        let row: Vec<_> = p.iter().filter(|q| q.0 == leg).collect();
        for w in row.windows(2) {
            out.push((leg, w[0].2, w[1].1));
        }
    }
    out
}

#[test]
fn counts_budgets_and_pedestals() {
    let l = load();
    assert!((80..=200).contains(&l.level.boxes.len()), "{} boxes", l.level.boxes.len());
    assert!(l.level.boxes.iter().all(|b| b.hp == 0.0), "the gauntlet is permanent geometry");
    assert!((14..=20).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    let cubes = l.pickups.iter().filter(|p| p.kind == PowerKind::None).count();
    let yumi = l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).count();
    let tags = l.pickups.iter().filter(|p| p.kind == PowerKind::Tag).count();
    assert!((6..=14).contains(&cubes), "{cubes} cubes");
    assert_eq!((yumi, tags), (2, 4), "bows and tag bags");
    assert!(l.pickups.iter().filter(|p| p.kind != PowerKind::None).all(|p| p.respawn_secs == 45.0));
    assert!(l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).all(|p| p.pos[1] > 30.0), "bows sit on the 30 m towers");
}

#[test]
fn five_legs_with_growing_gaps_and_every_gap_has_a_run_wall_and_a_hook_anchor() {
    let l = load();
    let g = gaps(&l);
    for leg in 0..5 {
        let row: Vec<_> = g.iter().filter(|q| q.0 == leg).collect();
        assert!(row.len() >= 4, "leg {leg}: only {} gaps", row.len());
        for q in &row {
            let w = q.2 - q.1;
            assert!((w - GAPS[leg]).abs() < 0.01, "leg {leg}: gap {w} m, expected {}", GAPS[leg]);
        }
    }
    assert!(GAPS.windows(2).all(|w| w[1] > w[0]), "the gaps grow with every leg");
    let cfg = Cfg::default();
    let run = cfg.wall_speed * cfg.wall_max_time;
    for (leg, x0, x1) in &g {
        let (xm, zc) = ((x0 + x1) / 2.0, LEG_Z[*leg]);
        // the run wall: tall, thin, beside the deck edge, its base on the deck, reaching >= 3.5 m over each side
        let panel = l
            .level
            .boxes
            .iter()
            .find(|b| b.rot_z == 0.0 && b.half[1] >= 3.4 && b.half[2] <= 0.51 && (b.center[0] - xm).abs() < 0.01 && (b.center[2] - zc).abs() > 5.0 && (b.center[2] - zc).abs() < 6.0)
            .unwrap_or_else(|| panic!("leg {leg}: no run wall over the gap {x0}..{x1}"));
        assert!((panel.center[1] - panel.half[1] - DECK).abs() < 0.01, "panel base is not on the deck: {panel:?}");
        assert!(panel.center[0] - panel.half[0] <= x0 - 3.5 && panel.center[0] + panel.half[0] >= x1 + 3.5, "panel {panel:?} does not overlap both decks");
        assert!(2.0 * panel.half[1] >= 6.9, "panel only {} m tall", 2.0 * panel.half[1]);
        assert!(2.0 * panel.half[0] >= (x1 - x0) + 7.0, "panel too short for the gap");
        // a run over the gap fits the engine's wall-run, or the anchor finishes it (the long gaps outlast one run)
        assert!(2.0 * panel.half[0] <= run + 12.0, "panel {} m vs wall-run {run} m", 2.0 * panel.half[0]);
        // the anchor: a floating slab hung 8..14 m over the gap middle on the leg axis
        let anchor = l
            .level
            .boxes
            .iter()
            .find(|b| (b.center[0] - xm).abs() < 0.5 && (b.center[2] - zc).abs() < 0.5 && b.center[1] > DECK + 8.0 && b.center[1] < DECK + 14.0)
            .unwrap_or_else(|| panic!("leg {leg}: no hook anchor over the gap {x0}..{x1}"));
        assert!(anchor.center[1] - anchor.half[1] > DECK + 8.0, "anchor {anchor:?} hangs too low to be a swing point");
        // alternating sides so a chain of runs weaves
    }
    for leg in 0..5 {
        let sides: Vec<f32> = g
            .iter()
            .filter(|q| q.0 == leg)
            .map(|(_, x0, x1)| {
                let xm = (x0 + x1) / 2.0;
                let p = l.level.boxes.iter().find(|b| b.half[1] >= 3.4 && b.half[2] <= 0.51 && (b.center[0] - xm).abs() < 0.01 && (b.center[2] - LEG_Z[leg]).abs() < 6.0 && (b.center[2] - LEG_Z[leg]).abs() > 5.0).unwrap();
                (p.center[2] - LEG_Z[leg]).signum()
            })
            .collect();
        assert!(sides.windows(2).all(|w| w[0] != w[1]), "leg {leg}: run walls do not alternate sides: {sides:?}");
    }
}

#[test]
fn spawns_stand_on_a_deck_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let top = top_at(&l, s[0], s[2]).expect("a spawn over void");
        assert!((top - (s[1] - reach)).abs() < 0.1, "spawn {s:?} floats or is buried (surface {top})");
        assert!((top - DECK).abs() < 0.01, "spawn {s:?} is not on a deck (surface {top})");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d3(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
    let max = nearest.iter().copied().fold(0.0, f32::max);
    assert!(max <= 70.0, "a spawn is {max:.1} m from its nearest neighbour");
    let far = far_dist(&l.level.spawns);
    assert!((20.0..=70.0).contains(&far), "preferred respawn distance {far:.1} m");
    // each leg carries spawns, so the first fight is in the air over the gaps
    for (leg, z) in LEG_Z.iter().enumerate() {
        let n = l.level.spawns.iter().filter(|s| (s[2] - z).abs() < 0.01).count();
        assert!(n >= 3, "leg {leg}: only {n} spawns");
    }
}

/// Flood the 1 m surface grid (highest surface per cell; neighbours join when the surface differs by <= 0.5 m) from the ground.
/// The turn pads (reached by the 22 degree ramps) are in the component, every platform between two gaps is NOT: the gaps
/// are the course. The tower tops are not either (hook only).
#[test]
fn ramps_lead_to_the_pads_and_the_platforms_between_the_gaps_need_the_run_walls_and_hooks() {
    let l = load();
    let (hx, hz) = (150i32, 76i32);
    let mut cells: HashMap<(i32, i32), f32> = HashMap::new();
    for x in -hx..hx {
        for z in -hz..hz {
            if let Some(t) = top_at(&l, x as f32 + 0.5, z as f32 + 0.5) {
                cells.insert((x, z), t);
            }
        }
    }
    let start = (0i32, -20i32);
    assert!(cells.get(&start).map_or(false, |h| h.abs() < 0.01), "the ground at the start cell");
    let mut seen: HashMap<(i32, i32), f32> = HashMap::new();
    let mut q = VecDeque::from([start]);
    seen.insert(start, cells[&start]);
    while let Some((x, z)) = q.pop_front() {
        let y = cells[&(x, z)];
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let c = (x + dx, z + dz);
            if seen.contains_key(&c) {
                continue;
            }
            if let Some(&ny) = cells.get(&c) {
                if (ny - y).abs() <= 0.5 {
                    seen.insert(c, ny);
                    q.push_back(c);
                }
            }
        }
    }
    // pads: the six 20 m end pads
    for (x, z) in [(-100.0f32, -56.0f32), (100.0, -42.0), (-100.0, -14.0), (100.0, 14.0), (-100.0, 42.0), (100.0, 56.0)] {
        assert!(seen.contains_key(&(x.floor() as i32, z.floor() as i32)), "pad at ({x}, {z}) is not reachable by the ramps");
    }
    // every platform whose both neighbours are gaps (an inner platform) is cut off on foot
    let p = platforms(&l);
    let mut inner = 0;
    for leg in 0..5 {
        let row: Vec<_> = p.iter().filter(|q| q.0 == leg).collect();
        for w in &row[1..row.len() - 1] {
            let (xc, zc) = (((w.1 + w.2) / 2.0).floor() as i32, LEG_Z[leg].floor() as i32);
            assert!(!seen.contains_key(&(xc, zc)), "inner platform of leg {leg} at x {xc} is walkable from the ground");
            inner += 1;
        }
    }
    assert!(inner >= 20, "{inner} inner platforms");
    // the hook towers' top plates are off the walkable network too
    let high = cells.iter().filter(|(c, h)| **h > 20.0 && !seen.contains_key(*c)).count();
    assert!(high >= 150, "only {high} tower / anchor cells are hook-only");
    // and no knee-high block blocks the ground
    assert!(unwalkable_obstacles(&l.level, Cfg::default().step_height).is_empty(), "jump-only obstacles on the gauntlet");
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let supported = l.level.boxes.iter().any(|b| surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3));
        assert!(supported, "pickup {:?} is not ~1 m above a surface", p.pos);
    }
}

#[test]
fn the_ground_has_void_edges_and_the_engine_numeric_limits_cover_the_map() {
    let l = load();
    assert_eq!(l.level.floor_half(), Some(150.0), "one ground floor, 300 m long");
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 150.01, "geometry reaches {far} m sideways");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    assert!((30.0..=40.0).contains(&top), "tallest geometry {top} m");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, 60.0, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - 60.0).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l);
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
